import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256
#define NUM_CHUNKS 128
__global__ void layernorm_partial_kernel(
    const float* __restrict__ x,
    int N,
    int num_chunks,
    int total_blocks,
    double* __restrict__ sum,
    double* __restrict__ sumsq)
{
    __shared__ double s_sum[BLOCK_SIZE / 32];
    __shared__ double s_sumsq[BLOCK_SIZE / 32];
    int tid = threadIdx.x;
    int stride = blockDim.x;
    unsigned mask = 0xffffffffu;
    for (int bid = blockIdx.x; bid < total_blocks; bid += gridDim.x) {
        int batch = bid / num_chunks;
        int chunk = bid % num_chunks;
        int chunk_size = (N + num_chunks - 1) / num_chunks;
        chunk_size = ((chunk_size + 3) / 4) * 4;
        int start = chunk * chunk_size;
        if (start > N) start = N;
        int end = start + chunk_size;
        if (end > N) end = N;
        const float* x_batch = x + (long long)batch * N;
        double local_sum = 0.0;
        double local_sumsq = 0.0;
        int vec_len = end - start;
        int num_vec = vec_len / 4;
        int vec_end = start + num_vec * 4;
        const float4* x_vec = reinterpret_cast<const float4*>(x_batch + start);
        for (int i = tid; i < num_vec; i += stride) {
            float4 v4 = x_vec[i];
            local_sum += (double)v4.x + (double)v4.y + (double)v4.z + (double)v4.w;
            local_sumsq += (double)v4.x * (double)v4.x + (double)v4.y * (double)v4.y +
                            (double)v4.z * (double)v4.z + (double)v4.w * (double)v4.w;
        }
        for (int i = vec_end + tid; i < end; i += stride) {
            float v = x_batch[i];
            local_sum += (double)v;
            local_sumsq += (double)v * (double)v;
        }
        for (int offset = 16; offset > 0; offset >>= 1) {
            local_sum += __shfl_down_sync(mask, local_sum, offset);
            local_sumsq += __shfl_down_sync(mask, local_sumsq, offset);
        }
        int warp_id = tid / 32;
        int lane_id = tid % 32;
        if (lane_id == 0) {
            s_sum[warp_id] = local_sum;
            s_sumsq[warp_id] = local_sumsq;
        }
        __syncthreads();
        if (warp_id == 0) {
            int num_warps = blockDim.x / 32;
            double warp_sum = (lane_id < num_warps) ? s_sum[lane_id] : 0.0;
            double warp_sumsq = (lane_id < num_warps) ? s_sumsq[lane_id] : 0.0;
            for (int offset = 16; offset > 0; offset >>= 1) {
                warp_sum += __shfl_down_sync(mask, warp_sum, offset);
                warp_sumsq += __shfl_down_sync(mask, warp_sumsq, offset);
            }
            if (lane_id == 0) {
                atomicAdd(&sum[batch], warp_sum);
                atomicAdd(&sumsq[batch], warp_sumsq);
            }
        }
        __syncthreads();
    }
}
__global__ void compute_stats_kernel(
    const double* __restrict__ sum,
    const double* __restrict__ sumsq,
    int N,
    int batch_count,
    float eps,
    float* __restrict__ mean,
    float* __restrict__ inv_std)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_count) return;
    double m = sum[idx] / (double)N;
    double var = sumsq[idx] / (double)N - m * m;
    mean[idx] = (float)m;
    inv_std[idx] = (float)(1.0 / sqrt(var + (double)eps));
}
__global__ void layernorm_apply_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ inv_std,
    int N,
    int num_chunks,
    int total_blocks)
{
    int tid = threadIdx.x;
    int stride = blockDim.x;
    for (int bid = blockIdx.x; bid < total_blocks; bid += gridDim.x) {
        int batch = bid / num_chunks;
        int chunk = bid % num_chunks;
        int chunk_size = (N + num_chunks - 1) / num_chunks;
        chunk_size = ((chunk_size + 3) / 4) * 4;
        int start = chunk * chunk_size;
        if (start > N) start = N;
        int end = start + chunk_size;
        if (end > N) end = N;
        const float* x_batch = x + (long long)batch * N;
        float* y_batch = y + (long long)batch * N;
        float m = mean[batch];
        float inv = inv_std[batch];
        int vec_len = end - start;
        int num_vec = vec_len / 4;
        int vec_end = start + num_vec * 4;
        const float4* x_vec = reinterpret_cast<const float4*>(x_batch + start);
        const float4* w_vec = reinterpret_cast<const float4*>(weight + start);
        const float4* b_vec = reinterpret_cast<const float4*>(bias + start);
        float4* y_vec = reinterpret_cast<float4*>(y_batch + start);
        for (int i = tid; i < num_vec; i += stride) {
            float4 xv = x_vec[i];
            float4 wv = w_vec[i];
            float4 bv = b_vec[i];
            float4 outv;
            outv.x = (xv.x - m) * inv * wv.x + bv.x;
            outv.y = (xv.y - m) * inv * wv.y + bv.y;
            outv.z = (xv.z - m) * inv * wv.z + bv.z;
            outv.w = (xv.w - m) * inv * wv.w + bv.w;
            y_vec[i] = outv;
        }
        for (int i = vec_end + tid; i < end; i += stride) {
            float v = x_batch[i];
            y_batch[i] = (v - m) * inv * weight[i] + bias[i];
        }
    }
}
torch::Tensor layernorm_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    auto x_contig = x.contiguous();
    auto weight_contig = weight.contiguous();
    auto bias_contig = bias.contiguous();
    auto y = torch::empty_like(x_contig);
    int64_t N = weight_contig.numel();
    int64_t total = x_contig.numel();
    int64_t batch = total / N;
    auto options_double = torch::TensorOptions().dtype(torch::kFloat64).device(x.device());
    auto options_float = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
    auto sum = torch::empty({batch}, options_double);
    auto sumsq = torch::empty({batch}, options_double);
    cudaMemsetAsync(sum.data_ptr<double>(), 0, (size_t)batch * sizeof(double));
    cudaMemsetAsync(sumsq.data_ptr<double>(), 0, (size_t)batch * sizeof(double));
    auto mean = torch::empty({batch}, options_float);
    auto inv_std = torch::empty({batch}, options_float);
    int num_chunks = NUM_CHUNKS;
    int total_blocks = (int)(batch * num_chunks);
    int device_id = 0;
    cudaGetDevice(&device_id);
    int sm_count = 1;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device_id);
    int blocks_per_sm = 1;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, layernorm_partial_kernel, BLOCK_SIZE, 0);
    if (blocks_per_sm < 1) blocks_per_sm = 1;
    int grid_size = sm_count * blocks_per_sm;
    if (grid_size > total_blocks) grid_size = total_blocks;
    if (grid_size < 1) grid_size = 1;
    dim3 grid_partial((unsigned int)grid_size);
    dim3 block(BLOCK_SIZE);
    layernorm_partial_kernel<<<grid_partial, block>>>(
        x_contig.data_ptr<float>(),
        (int)N,
        num_chunks,
        total_blocks,
        sum.data_ptr<double>(),
        sumsq.data_ptr<double>()
    );
    int stats_block = 128;
    int stats_grid = (int)((batch + stats_block - 1) / stats_block);
    compute_stats_kernel<<<stats_grid, stats_block>>>(
        sum.data_ptr<double>(),
        sumsq.data_ptr<double>(),
        (int)N,
        (int)batch,
        (float)eps,
        mean.data_ptr<float>(),
        inv_std.data_ptr<float>()
    );
    layernorm_apply_kernel<<<grid_partial, block>>>(
        x_contig.data_ptr<float>(),
        y.data_ptr<float>(),
        weight_contig.data_ptr<float>(),
        bias_contig.data_ptr<float>(),
        mean.data_ptr<float>(),
        inv_std.data_ptr<float>(),
        (int)N,
        num_chunks,
        total_blocks
    );
    return y;
}
